arguments.command:
whoami; id -un; printf '\n--- perms/locked ---\n'; stat -f '%Sp %Su %Sg %z %N' data/locked/payroll.bin; printf '\n--- symlinks ---\n'; for f in data/hosts data/latest.csv data/loop; do printf '%s -> ' "$f"; readlink "$f"; done; printf '\n--- filename bytes (non-ascii) ---\n'; find data -mindepth 1 -name '*' -print0 | python3 -c '
import sys,unicodedata
for b in sys.stdin.buffer.read().split(b"\0"):
    if not b: continue
    try: s=b.decode("utf-8")
    except Exception as e: print("BADUTF8",b); continue
    if any(ord(c)>126 or ord(c)<32 for c in s):
        print(repr(s), "NFC" if unicodedata.is_normalized("NFC",s) else "not-NFC", "NFD" if unicodedata.is_normalized("NFD",s) else "not-NFD")
'

